//! The built-in layer types, outside the engine.
//!
//! Each type is a module that holds its marker type, which implements
//! `mln_style`'s `StyleLayerType` and `mln_renderer`'s `LayerType`, its
//! property sets (`properties.rs`, generated by //tools/style-codegen from
//! the style spec) and its render layer, and for a type that lays out, its
//! bucket and its layout; the fill, line and fill-extrusion layouts are a
//! `PatternLayout` of each type. The raster, hillshade and color-relief
//! types draw the engine's raster and raster-dem tile contents. The other
//! built-in layer types are in the engine, and register through
//! `mln_renderer::builtins::register_layer_types`.

pub mod background;
pub mod circle;
mod color_ramp;
pub mod color_relief;
pub mod fill;
pub mod fill_extrusion;
pub mod heatmap;
pub mod hillshade;
pub mod line;
mod pattern_layout;
pub mod raster;

pub use background::{Background, BackgroundPaintProperties};
pub use circle::{Circle, CircleLayoutProperties, CirclePaintProperties};
pub use color_relief::{ColorRelief, ColorReliefPaintProperties};
pub use fill::{Fill, FillLayoutProperties, FillPaintProperties};
pub use fill_extrusion::{FillExtrusion, FillExtrusionLayoutProperties, FillExtrusionPaintProperties};
pub use heatmap::{Heatmap, HeatmapPaintProperties};
pub use hillshade::{Hillshade, HillshadePaintProperties};
pub use line::{Line, LineLayoutProperties, LinePaintProperties};
use mln_renderer::unstable::{BucketChanges, DrawObjects, VertexAttributeArray};
use mln_renderer::{RegisterError, RegistryBuilder};
pub use raster::{Raster, RasterPaintProperties};

/// Adds the layer types of this crate. Fails for a name that an earlier
/// call took.
pub fn register_layer_types(builder: &mut RegistryBuilder) -> Result<(), RegisterError> {
    builder.add_layer_type::<Background>()?;
    builder.add_layer_type::<Fill>()?;
    builder.add_layer_type::<Line>()?;
    builder.add_layer_type::<Circle>()?;
    builder.add_layer_type::<FillExtrusion>()?;
    builder.add_layer_type::<Heatmap>()?;
    builder.add_layer_type::<Raster>()?;
    builder.add_layer_type::<Hillshade>()?;
    builder.add_layer_type::<ColorRelief>()
}

/// Copies a bucket's data-driven attributes into a draw again where
/// `changes` says their values changed: `refresh(attrs)` reads them into its
/// instance attributes where it has them, else into its vertex attributes,
/// which then upload again.
fn refresh_paint_attributes(
    objects: &mut DrawObjects,
    changes: BucketChanges,
    refresh: impl FnOnce(&mut VertexAttributeArray),
) {
    if !changes.paint {
        return;
    }
    refresh(objects.paint_attributes_mut());
}

